local SortingMachineMaker = {}
local PRODUCTS = {
    simple_wood_sorting = { name = "Preprost leseni sortilni stroj", woodCost = 4, ironCost = 1, time = 5, cost = 130, food = 18, happiness = 1, description = "Preprost leseni sortilni stroj za sortiranje." },
    iron_sieve_sorting = { name = "Železnosito sortilni stroj", woodCost = 4, ironCost = 2, time = 7, cost = 320, food = 30, happiness = 2, prestige = 2, description = "Železnosito sortilni stroj za trgovce." },
    silver_geared_sorting = { name = "Srebrnozobčani sortilni stroj", woodCost = 4, silverCost = 1, ironCost = 2, time = 11, cost = 760, food = 45, happiness = 2, prestige = 6, description = "Srebrnozobčani sortilni stroj za plemiče." },
    gold_trimmed_sorting = { name = "Zlatookrasni sortilni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, time = 15, cost = 1800, food = 60, happiness = 3, prestige = 14, description = "Zlatookrasni sortilni stroj za visoke plemiče." },
    jewel_set_sorting = { name = "Draguljasta sortilni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, jewelCost = 1, time = 19, cost = 3900, food = 75, happiness = 5, prestige = 27, description = "Sortilni stroj z draguljem za visoko plemstvo." },
    royal_grand_sorting = { name = "Kraljevski veliki sortilni stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 8500, food = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski sortilni stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sorting_workshop = { name = "Sortilna delavnica", cost = { gold = 280, wood = 160, stone = 140, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_sorting_atelier = { name = "Mojstrski sortilni atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
SortingMachineMaker.woodStock = 20; SortingMachineMaker.ironStock = 12; SortingMachineMaker.silverStock = 6; SortingMachineMaker.goldStock = 6; SortingMachineMaker.jewelStock = 4; SortingMachineMaker.pearlStock = 4
SortingMachineMaker.productStock = {}; SortingMachineMaker.buildings = {}; SortingMachineMaker.maker = nil; SortingMachineMaker.activeMaking = {}; SortingMachineMaker.totalProducts = 0; SortingMachineMaker.dayTimer = 0
function SortingMachineMaker.init() SortingMachineMaker.woodStock=20; SortingMachineMaker.ironStock=12; SortingMachineMaker.silverStock=6; SortingMachineMaker.goldStock=6; SortingMachineMaker.jewelStock=4; SortingMachineMaker.pearlStock=4; SortingMachineMaker.productStock={}; SortingMachineMaker.buildings={}; SortingMachineMaker.maker=nil; SortingMachineMaker.activeMaking={}; SortingMachineMaker.totalProducts=0; SortingMachineMaker.dayTimer=0; print("[SortingMachineMaker] Royal Sorting Machine Maker System initialized (6 products, 4 buildings)") end
function SortingMachineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SortingMachineMaker.maker={name=n or ("Sortilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sortilnikar najet: %s (spretnost: %d)",SortingMachineMaker.maker.name,s),"success") end; return true end
function SortingMachineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SortingMachineMaker.build(id) local ok,e=SortingMachineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SortingMachineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SortingMachineMaker.getQualityBonus() local b=0; for _,bd in ipairs(SortingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SortingMachineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SortingMachineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and SortingMachineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and SortingMachineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SortingMachineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SortingMachineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SortingMachineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SortingMachineMaker.buildings==0 then return false,"Potrebna sortilna delavnica" end; if not SortingMachineMaker.maker then return false,"Potreben sortilnikar" end; return true end
function SortingMachineMaker.make(pt,qty) qty=qty or 1; local ok,e=SortingMachineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SortingMachineMaker.woodStock=SortingMachineMaker.woodStock-d.woodCost*qty end; if d.ironCost then SortingMachineMaker.ironStock=SortingMachineMaker.ironStock-d.ironCost*qty end; if d.silverCost then SortingMachineMaker.silverStock=SortingMachineMaker.silverStock-d.silverCost*qty end; if d.goldCost then SortingMachineMaker.goldStock=SortingMachineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SortingMachineMaker.jewelStock=SortingMachineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SortingMachineMaker.pearlStock=SortingMachineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SortingMachineMaker.maker then t=math.max(1,t-math.floor(SortingMachineMaker.maker.skill/13)) end; table.insert(SortingMachineMaker.activeMaking,{id="sortingmachine_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SortingMachineMaker.completeMaking(m) local q=1.0+(SortingMachineMaker.getQualityBonus()/100); if SortingMachineMaker.maker then q=q+(SortingMachineMaker.maker.skill/140) end; q=math.min(2.5,q); SortingMachineMaker.productStock[m.productType]=(SortingMachineMaker.productStock[m.productType] or 0)+m.quantity; SortingMachineMaker.totalProducts=SortingMachineMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SortingMachineMaker.maker then SortingMachineMaker.maker.itemsMade=SortingMachineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SortingMachineMaker.maker.skill=math.min(100,SortingMachineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sortilni stroj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sortingmachine.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function SortingMachineMaker.update(dt) if not _G.state then return end; SortingMachineMaker.dayTimer=SortingMachineMaker.dayTimer+dt; if SortingMachineMaker.dayTimer>=30 then SortingMachineMaker.dayTimer=0; for i=#SortingMachineMaker.activeMaking,1,-1 do local m=SortingMachineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SortingMachineMaker.completeMaking(m); table.remove(SortingMachineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SortingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SortingMachineMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SortingMachineMaker.getStats() return {woodStock=SortingMachineMaker.woodStock,ironStock=SortingMachineMaker.ironStock,silverStock=SortingMachineMaker.silverStock,goldStock=SortingMachineMaker.goldStock,jewelStock=SortingMachineMaker.jewelStock,pearlStock=SortingMachineMaker.pearlStock,productStock=SortingMachineMaker.productStock,numBuildings=#SortingMachineMaker.buildings,hasMaker=SortingMachineMaker.maker~=nil,makerName=SortingMachineMaker.maker and SortingMachineMaker.maker.name or "—",makerSkill=SortingMachineMaker.maker and SortingMachineMaker.maker.skill or 0,activeMaking=#SortingMachineMaker.activeMaking,totalProducts=SortingMachineMaker.totalProducts} end
return SortingMachineMaker
